// TWO CONSECUTIVE FAILURES before alerting. One 15-minute blip is usually a
// restart or a redeploy; paging on it teaches everyone to ignore the alert,
// which costs more than the blip. Two in a row is a state, not an event.
//
// State lives in $getWorkflowStaticData('global'), which n8n persists on the
// workflow record. It survives restarts. Two limits, both verified rather than
// assumed, because a counter that silently fails to persist would mean this
// alert NEVER fires — the worst possible failure for a monitor:
//   * It is saved for PRODUCTION runs only. A manual `n8n execute` does not
//     persist it, so the two-strike behaviour cannot be exercised by hand — the
//     first strike will simply repeat forever. Confirmed on a real scheduled
//     tick, which did persist consecutiveFailures:1.
//   * It does NOT survive a re-import of this workflow, so the first failure
//     after a re-import is silent even if the door was already shut.
const st = $getWorkflowStaticData('global');
const r = $input.first().json || {};
const code = Number(r.statusCode ?? 0);
const NL = String.fromCharCode(10);

const prevFails = Number(st.consecutiveFailures || 0);
const hadAlerted = !!st.alerted;

// A 200 only counts with ok:true in the body. The door used to answer 200
// "Workflow was started" to every caller before checking anything, so a
// status-only check read a locked door as open. Requiring the body means a
// regression to that answer-on-receipt shape alarms instead of passing.
const opened = code === 200 && !!r.body && r.body.ok === true;
if (opened) {
  st.consecutiveFailures = 0;
  st.alerted = false;
  // RECOVERY is worth one message, but only if we actually raised the alarm.
  // A silent recovery leaves someone believing the outage is still open.
  if (hadAlerted) {
    // Recovering from a BLIND probe is not the same as the door coming back: we
    // never knew it was down. Saying 'door is BACK' there would assert an outage
    // that was never observed, which is the same over-claim the fault titles
    // exist to avoid.
    const wasBlind = st.lastFault === 'blind';
    st.lastFault = null;
    return [{ json: {
      severity: 'info',
      title: wasBlind
        ? 'ask-human heartbeat can SEE again (HTTP 200)'
        : 'ask-human door is BACK (HTTP 200)',
      message: [
        'POST /webhook/ask-human is answering again.',
        '',
        wasBlind
          ? 'The probe had been unable to authenticate for ' + prevFails
            + ' consecutive checks, so the state of the door was unknown for that '
            + 'window. It is confirmed open now.'
          : 'It had failed ' + prevFails
            + ' consecutive checks. Agents can reach a human again.',
      ].join(NL),
      source: 'seam-heartbeat',
    } }];
  }
  return [];
}

const fails = prevFails + 1;
st.consecutiveFailures = fails;

// Strike one is silent. After alerting, go quiet but re-raise every 4th check
// (hourly at a 15-minute cadence) so a forgotten outage does not fade away.
const firstAlert = fails === 2;
const reminder = hadAlerted && fails % 4 === 0;
if (!firstAlert && !reminder) { return []; }
st.alerted = true;

let title, why;
if (code === 404) {
  title = 'ask-human door is SHUT (404 - path not registered)';
  why = 'The path is not registered. Most likely an ORPHANED webhook registration '
      + 'is squatting it, which survives a restart and cannot be cleared from the '
      + 'n8n UI. Run: python scripts/n8n_doctor.py';
} else if (!code) {
  title = 'ask-human door UNREACHABLE (no HTTP response)';
  why = 'Timeout or connection refused. n8n itself may be down - though if it were, '
      + 'this probe would not have run either, so suspect the network or the port.';
} else if (code === 401 || code === 403) {
  title = 'ask-human heartbeat is BLIND (HTTP ' + code + ')';
  why = 'The probe could not authenticate, so the state of the door is UNKNOWN - it '
      + 'may be perfectly fine. Fix ASK_HUMAN_TOKEN for the probe; this is not an outage.';
} else if (code === 503) {
  title = 'ask-human door is SHUT (503 - n8n has no ASK_HUMAN_TOKEN)';
  why = 'n8n is running without ASK_HUMAN_TOKEN, so the door refuses every caller. '
      + 'Set it in .env and recreate n8n.';
} else if (code === 200) {
  title = 'ask-human door answered 200 WITHOUT checking (no ok:true)';
  why = 'The webhook replied before the auth node ran, which is the answer-on-receipt '
      + 'shape that hid rejections. Its responseMode must be responseNode.';
} else {
  title = 'ask-human door returned HTTP ' + code;
  why = 'Unexpected status. The path answered, so it is registered; something past '
      + 'the webhook is wrong.';
}

const blind = (code === 401 || code === 403);
st.lastFault = blind ? 'blind' : 'down';
const mins = fails * 15;

return [{ json: {
  severity: 'error',
  title: title + (reminder ? ' - still down' : ''),
  message: [
    'POST /webhook/ask-human returned ' + (code || 'no response') + ' on '
      + fails + ' consecutive checks (~' + mins + ' minutes).',
    '',
    why,
    '',
    blind
      ? 'IMPACT: unknown. This alert means the CHECK is broken, not necessarily the door.'
      : 'IMPACT: agents cannot reach a human mid-run. A run that needs one will not ask '
        + 'and will not fail loudly - it proceeds without the answer.',
  ].join(NL),
  source: 'seam-heartbeat',
} }];
